<?php
namespace App\Http\Controllers;
use App\Models\{Product,Order,OrderItem,UserNotification,PickupSlot};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Carbon\Carbon;
use App\Services\{ActivityLogger,MarketLinkMailService};
class OrderController extends Controller {
    public function create(Request $r){$items=$r->validate(['product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1']);$p=Product::with(['farmer.farmerProfile','market'])->findOrFail($items['product_id']);abort_if(!$p->is_available||$items['quantity']>$p->stock_quantity,422,'Requested quantity is unavailable.');$slots=PickupSlot::where('farmer_id',$p->farmer_id)->when($p->market_id,fn($q)=>$q->where('market_id',$p->market_id),fn($q)=>$q->whereNull('market_id'))->whereDate('slot_date','>=',today())->whereDate('slot_date','<=',today()->addDays(30))->where('is_active',1)->orderBy('slot_date')->orderBy('start_time')->get();return view('orders.create',compact('p','items','slots'));}
    public function store(Request $r){$d=$r->validate(['product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1','pickup_slot_id'=>'required|integer|exists:pickup_slots,id','notes'=>'nullable|string|max:1000']);$order=DB::transaction(function()use($d){$p=Product::lockForUpdate()->findOrFail($d['product_id']);abort_if(!$p->is_available||$d['quantity']>$p->stock_quantity,422,'Stock is no longer available.');$slot=PickupSlot::lockForUpdate()->findOrFail($d['pickup_slot_id']);$this->validateSlotForProduct($slot,$p);$this->validateSlotCapacity($slot,null);$this->validateCutoffForDate($p->farmer,$slot->slot_date);$total=$p->price*$d['quantity'];$o=Order::create(['order_number'=>'ML-'.now()->format('ymdHis').'-'.Str::upper(Str::random(4)),'customer_id'=>auth()->id(),'farmer_id'=>$p->farmer_id,'market_id'=>$p->market_id,'pickup_date'=>$slot->slot_date->toDateString(),'pickup_slot'=>$slot->label(),'status'=>'placed','total_amount'=>$total,'notes'=>$d['notes']??null,'placed_at'=>now()]);OrderItem::create(['order_id'=>$o->id,'product_id'=>$p->id,'quantity'=>$d['quantity'],'unit_price'=>$p->price,'line_total'=>$total]);$p->decrement('stock_quantity',$d['quantity']);return $o;});$this->notifyOrder($order,'New pre-order','Order '.$order->order_number.' is waiting for your approval.',$order->farmer);ActivityLogger::log('order.created','Customer placed order '.$order->order_number,'Order',$order->id);return redirect()->route('customer.orders.show',$order)->with('success','Pre-order placed successfully. Pay in person at pickup.');}
    public function customerOrders(Request $r){$allowed=['placed','accepted','ready','completed','cancelled','declined'];if($r->filled('status')&&!in_array($r->status,$allowed,true))abort(422);$orders=Order::with(['items.product','farmer','market'])->where('customer_id',auth()->id())->when($r->status,fn($q)=>$q->where('status',$r->status))->latest()->paginate(10)->withQueryString();return view('orders.customer',compact('orders'));}
    public function customerShow(Order $order){abort_unless($order->customer_id===auth()->id(),403);$order->load(['items.product.reviews'=>fn($q)=>$q->where('customer_id',auth()->id()),'farmer.farmerProfile','market']);return view('orders.show',compact('order'));}
    public function customerEdit(Order $order){abort_unless($order->customer_id===auth()->id(),403);$order->load(['items.product','farmer.farmerProfile','market']);$this->assertModifiable($order);$slots=PickupSlot::where('farmer_id',$order->farmer_id)->when($order->market_id,fn($q)=>$q->where('market_id',$order->market_id),fn($q)=>$q->whereNull('market_id'))->whereDate('slot_date','>=',today())->whereDate('slot_date','<=',today()->addDays(30))->where('is_active',1)->orderBy('slot_date')->orderBy('start_time')->get();return view('orders.edit',compact('order','slots'));}
    public function customerUpdate(Request $r,Order $order){abort_unless($order->customer_id===auth()->id(),403);$d=$r->validate(['pickup_slot_id'=>'required|integer|exists:pickup_slots,id','notes'=>'nullable|string|max:1000','items'=>'required|array']);DB::transaction(function()use($order,$d){$o=Order::with(['items.product','farmer'])->lockForUpdate()->findOrFail($order->id);$this->assertModifiable($o);$slot=PickupSlot::lockForUpdate()->findOrFail($d['pickup_slot_id']);$reference=$o->items->first()?->product;$this->validateSlotForProduct($slot,$reference);$this->validateCutoffForDate($o->farmer,$slot->slot_date);$used=Order::where('farmer_id',$o->farmer_id)->whereDate('pickup_date',$slot->slot_date)->where('pickup_slot',$slot->label())->whereIn('status',['placed','accepted','ready'])->whereKeyNot($o->id)->count();abort_if($used >= $slot->capacity,422,'That pickup slot is full.');$newTotal=0;
            foreach($o->items as $item){$newQty=(int)($d['items'][$item->id]['quantity']??0);abort_if($newQty<0||$newQty>100000,422,'Invalid quantity.');$p=Product::lockForUpdate()->find($item->product_id);abort_unless($p,422,'A product in this order is no longer available.');$oldQty=(int)$item->quantity;if($newQty>$oldQty){$delta=$newQty-$oldQty;abort_if(!$p->is_available||$p->stock_quantity<$delta,422,'Not enough stock for '.$p->name.'.');$p->decrement('stock_quantity',$delta);}elseif($newQty<$oldQty){$p->increment('stock_quantity',$oldQty-$newQty);}if($newQty===0){$item->delete();continue;}$item->update(['quantity'=>$newQty,'unit_price'=>$p->price,'line_total'=>$p->price*$newQty]);$newTotal += (float)$p->price*$newQty;}
            abort_if($o->items()->count()===0,422,'Your order must contain at least one product.');$o->update(['pickup_date'=>$slot->slot_date->toDateString(),'pickup_slot'=>$slot->label(),'total_amount'=>$newTotal,'notes'=>$d['notes']??null]);
        });$this->notifyOrder($order->fresh()->load('farmer'),'Order updated','Customer updated order '.$order->order_number.'.',$order->farmer);ActivityLogger::log('order.updated','Customer modified order '.$order->order_number,'Order',$order->id);return redirect()->route('customer.orders.show',$order)->with('success','Order updated successfully.');}
    public function farmerOrders(Request $r){$allowed=['placed','accepted','ready','completed','cancelled','declined'];if($r->filled('status')&&!in_array($r->status,$allowed,true))abort(422);$orders=Order::with(['items.product','customer','market'])->where('farmer_id',auth()->id())->when($r->status,fn($q)=>$q->where('status',$r->status))->latest()->paginate(10)->withQueryString();return view('farmer.orders',compact('orders'));}
    public function farmerShow(Order $order){abort_unless($order->farmer_id===auth()->id(),403);$order->load(['items.product','customer','market']);return view('farmer.order-show',compact('order'));}
    public function status(Request $r,Order $order){abort_unless($order->farmer_id===auth()->id(),403);$new=$r->validate(['status'=>'required|in:accepted,ready,completed,declined,cancelled'])['status'];DB::transaction(function()use($order,$new){$o=Order::with('items.product')->lockForUpdate()->findOrFail($order->id);$allowed=['placed'=>['accepted','declined'],'accepted'=>['ready','cancelled'],'ready'=>['completed']];abort_unless(isset($allowed[$o->status])&&in_array($new,$allowed[$o->status],true),422,'This order cannot be moved to that status.');if(in_array($new,['declined','cancelled'],true))foreach($o->items as $item)$item->product?->increment('stock_quantity',$item->quantity);$o->update(['status'=>$new]);$label=['accepted'=>'accepted','declined'=>'declined','ready'=>'ready for pickup','completed'=>'completed','cancelled'=>'cancelled by the farmer'][$new];UserNotification::create(['user_id'=>$o->customer_id,'title'=>'Order update','message'=>'Order '.$o->order_number.' has been '.$label.'.','type'=>'order']);});$fresh=$order->fresh()->load(['customer','farmer']);MarketLinkMailService::send($fresh->customer?->email,'MarketLink order '.$fresh->status,'Order '.$fresh->order_number.' is now '.$fresh->status.'. Pickup: '.$fresh->pickup_date->format('d M Y').' · '.$fresh->pickup_slot.'.');ActivityLogger::log('order.status','Farmer moved order '.$order->order_number.' to '.$new,'Order',$order->id);return back()->with('success','Order status updated successfully.');}
    public function cancel(Request $request,Order $order){abort_unless($order->customer_id===auth()->id(),403);DB::transaction(function()use($order){$o=Order::with(['items.product','farmer'])->lockForUpdate()->findOrFail($order->id);$this->assertModifiable($o);foreach($o->items as $item)$item->product?->increment('stock_quantity',$item->quantity);$o->update(['status'=>'cancelled']);UserNotification::create(['user_id'=>$o->farmer_id,'title'=>'Order cancelled','message'=>'Customer cancelled order '.$o->order_number.'. Stock has been released.','type'=>'order']);});$fresh=$order->fresh()->load('farmer');MarketLinkMailService::send($fresh->farmer?->email,'MarketLink order cancelled','Customer cancelled order '.$fresh->order_number.'.');ActivityLogger::log('order.cancelled','Customer cancelled order '.$order->order_number,'Order',$order->id);if($request->expectsJson()){return response()->json(['message'=>'Order cancelled and stock restored.','order_id'=>$order->id,'status'=>'cancelled','reorder_url'=>route('orders.reorder',$order)]);}return back()->with('success','Order cancelled and stock restored.');}
    public function reorder(Order $order){abort_unless($order->customer_id===auth()->id(),403);abort_unless(in_array($order->status,['completed','cancelled','declined'],true),422,'Reorder is available from a past order.');foreach($order->items()->with('product')->get() as $item){$p=$item->product;if($p&&$p->is_available&&$p->stock_quantity>0){$cart=\App\Models\CartItem::firstOrNew(['user_id'=>auth()->id(),'product_id'=>$p->id]);$cart->quantity=min((int)$p->stock_quantity,(int)$cart->quantity+(int)$item->quantity);$cart->save();}}return redirect()->route('cart.index')->with('success','Available items from the previous order were added to your cart.');}
    public function receipt(Order $order){abort_unless($order->customer_id===auth()->id()||$order->farmer_id===auth()->id()||auth()->user()->role==='admin',403);$order->load(['items.product','customer','farmer','market']);return view('orders.receipt',compact('order'));}
    public function exportOrders(){if(auth()->user()->role==='farmer')$orders=auth()->user()->farmerOrders();else $orders=auth()->user()->customerOrders();$orders=$orders->with(['customer','farmer','market','items.product'])->latest()->get();return response()->streamDownload(function()use($orders){$o=fopen('php://output','w');fputcsv($o,['Order','Customer','Farmer','Market','Pickup','Status','Items','Total']);foreach($orders as $x)fputcsv($o,[$x->order_number,$x->customer->name,$x->farmer->name,$x->market?->name,$x->pickup_date->format('Y-m-d').' '.$x->pickup_slot,$x->status,$x->items->pluck('product.name')->join(' | '),$x->total_amount]);fclose($o);},'marketlink-orders.csv',['Content-Type'=>'text/csv']);}
    private function validateSlotForProduct($slot,$p){abort_unless($p&& (int)$slot->farmer_id===(int)$p->farmer_id,422,'Invalid pickup slot.');if($p->market_id)abort_unless((int)$slot->market_id===(int)$p->market_id,422,'Pickup slot does not match this market.');else abort_unless($slot->market_id===null,422,'Pickup slot does not match this product.');abort_unless($slot->is_active&&!$slot->slot_date->lt(today()),422,'Pickup slot is no longer available.');}
    private function validateSlotCapacity($slot,$ignoreOrderId=null){$q=Order::where('farmer_id',$slot->farmer_id)->whereDate('pickup_date',$slot->slot_date)->where('pickup_slot',$slot->label())->whereIn('status',['placed','accepted','ready']);if($ignoreOrderId)$q->whereKeyNot($ignoreOrderId);abort_if($q->count()>=$slot->capacity,422,'That pickup slot is full.');}
    private function validateCutoffForDate($farmer,$date){$cutoff=$farmer->farmerProfile?->order_cutoff_time;if($cutoff){$time=Carbon::parse($date->toDateString().' '.$cutoff->format('H:i:s'));if($date->isToday())abort_if(now()->gt($time),422,'The farmer cutoff time for today has passed.');else abort_if(now()->gt($date->copy()->subDay()->setTimeFromTimeString($cutoff->format('H:i:s'))),422,'The cutoff for this pickup date has passed.');}elseif($date->isToday())abort_if(now()->gt(today()->setTime(20,0)),422,'The default 8:00 PM cutoff has passed.');else abort_if(now()->gt($date->copy()->subDay()->setTime(20,0)),422,'The default cutoff for this pickup date has passed.');}
    private function assertModifiable(Order $order){abort_unless(in_array($order->status,['placed','accepted'],true),422,'This order can no longer be modified.');$this->validateCutoffForDate($order->farmer,$order->pickup_date);}
    private function notifyOrder(Order $order,string $title,string $message,$recipient=null):void{$uid=$recipient?->id??$order->farmer_id;UserNotification::create(['user_id'=>$uid,'title'=>$title,'message'=>$message,'type'=>'order']);if($recipient)MarketLinkMailService::send($recipient->email,'MarketLink · '.$title,$message);}
}
